// ==============================================================================
// MULTI-CHANNEL PRODUCTION MATRIX CONFIGURATION
// Chứa danh sách N kênh, thể loại (genre), prompt ý tưởng và credentials YouTube
// ==============================================================================

return [
  {
    json: {
      channelId: 'channel_01_paper',
      channelName: 'Paper Theater World (History)',
      genreKey: 'paper_history',
      title: 'The Real Reason Julius Caesar Crossed the Rubicon',
      prompt: 'Focus on high political tension and financial ruin if he laid down arms.',
      category: 'ancient_history',
      // Nếu để trống credentials, hệ thống tự động dùng keys đã lưu trong DB hoặc .env
      youtube: {
        clientId: '',
        clientSecret: '',
        refreshToken: ''
      }
    }
  },
  {
    json: {
      channelId: 'channel_02_tech',
      channelName: 'Quantum Horizon (Tech & AI)',
      genreKey: 'cyberpunk_tech',
      title: 'Quantum Supremacy: How Qubits Will Shatter Modern Cryptography',
      prompt: 'Explain the 30-second thrill of RSA encryption collapsing before quantum computers.',
      category: 'technology',
      youtube: {
        clientId: $env.YOUTUBE_CH2_CLIENT_ID || '',
        clientSecret: $env.YOUTUBE_CH2_CLIENT_SECRET || '',
        refreshToken: $env.YOUTUBE_CH2_REFRESH_TOKEN || ''
      }
    }
  },
  {
    json: {
      channelId: 'channel_03_stoic',
      channelName: 'Iron Mind (Dark Stoicism)',
      genreKey: 'dark_stoic',
      title: 'Marcus Aurelius on Betrayal: The Inner Citadel',
      prompt: 'Uncompromising stoic truth on why you must expect malice and how to remain invincible.',
      category: 'philosophy',
      youtube: {
        clientId: $env.YOUTUBE_CH3_CLIENT_ID || '',
        clientSecret: $env.YOUTUBE_CH3_CLIENT_SECRET || '',
        refreshToken: $env.YOUTUBE_CH3_REFRESH_TOKEN || ''
      }
    }
  }
];

